/*
 * sounds.js — UI sound playback through WebAudio.
 *
 *   UISound.play("click")              play sounds/click.wav
 *   UISound.play("slider", { rate })   optional playback rate
 *
 * Buffers are decoded once and mixed in-page (no engine round-trip), so even
 * rapid hover sounds have no latency. The master gain follows the engine's
 * "volume" cvar times "htmlui_sound_volume" (page-side setting, 0..1).
 * The set is generated by sounds/generate_sounds.ps1.
 */
(function (global) {
  'use strict';

  const NAMES = ['hover', 'click', 'back', 'open', 'tab', 'toggle_on', 'toggle_off', 'slider', 'error', 'notify', 'success', 'start', 'quit'];
  const MIN_INTERVAL = { hover: 0.035, slider: 0.03, tab: 0.03 };

  let ctx = null;
  let master = null;
  const buffers = new Map();
  const lastPlayed = new Map();
  let gameVolume = 1;
  let uiVolume = 0.8;
  let enabled = true;

  function ensureContext() {
    if (ctx) return ctx;
    const AC = global.AudioContext || global.webkitAudioContext;
    if (!AC) return null;
    ctx = new AC({ latencyHint: 'interactive' });
    master = ctx.createGain();
    master.connect(ctx.destination);
    applyGain();
    return ctx;
  }

  function applyGain() {
    if (master) master.gain.value = Math.max(0, Math.min(1, gameVolume * uiVolume));
  }

  async function load(name) {
    const res = await fetch(`sounds/${name}.wav`);
    if (!res.ok) throw new Error(`sound ${name}: HTTP ${res.status}`);
    const data = await res.arrayBuffer();
    buffers.set(name, await ctx.decodeAudioData(data));
  }

  async function init() {
    if (!ensureContext()) return;
    await Promise.all(NAMES.map((n) => load(n).catch((e) => console.warn(e.message))));
  }

  function play(name, { rate = 1, gain = 1 } = {}) {
    if (!enabled || !ensureContext()) return;
    const buf = buffers.get(name);
    if (!buf) return;
    const now = ctx.currentTime;
    const min = MIN_INTERVAL[name] || 0;
    if (min && now - (lastPlayed.get(name) || -1) < min) return;
    lastPlayed.set(name, now);
    if (ctx.state === 'suspended') ctx.resume();

    const src = ctx.createBufferSource();
    src.buffer = buf;
    src.playbackRate.value = rate;
    const g = ctx.createGain();
    g.gain.value = gain;
    src.connect(g).connect(master);
    src.start();
  }

  global.UISound = {
    init,
    play,
    setGameVolume(v) { gameVolume = Number(v) || 0; applyGain(); },
    setUiVolume(v) { uiVolume = Number(v) || 0; applyGain(); },
    setEnabled(v) { enabled = !!v; },
    get names() { return NAMES.slice(); },
  };
})(window);
